-- Restore source CHECK, UNIQUE and relational constraints while preserving the migrated rows.
-- Auth-related constraints are intentionally deferred until the supported Auth migration is complete.
begin;
alter table public.bank_accounts drop constraint "bank_accounts_company_fk";
alter table public.categories drop constraint "categories_company_fk";
alter table public.erp_account_mappings drop constraint "erp_mappings_company_fk";
alter table public.goals drop constraint "goals_company_fk";
alter table public.inventory_snapshots drop constraint "inventory_company_fk";
