alter table public.transactions drop constraint "transactions_bank_account_fk";
alter table public.transactions drop constraint "transactions_category_fk";
alter table public.transactions drop constraint "transactions_company_fk";
alter table public.transactions drop constraint "transactions_cost_center_fk";
alter table public.company_members drop constraint company_members_pkey;
alter table public.bank_accounts add constraint "bank_accounts_company_id_fkey" FOREIGN KEY (company_id) REFERENCES companies(id) ON DELETE CASCADE;
alter table public.categories add constraint "categories_company_id_fkey" FOREIGN KEY (company_id) REFERENCES companies(id) ON DELETE CASCADE;
