alter table public.company_invitations add constraint "company_invitations_invite_type_chk" CHECK ((invite_type = ANY (ARRAY['email'::text, 'link'::text])));
alter table public.company_invitations add constraint "company_invitations_link_token_chk" CHECK (((invite_type <> 'link'::text) OR (token_hash IS NOT NULL)));
alter table public.company_invitations add constraint "company_invitations_status_check" CHECK ((status = ANY (ARRAY['pending'::text, 'accepted'::text, 'expired'::text, 'cancelled'::text, 'failed'::text])));
alter table public.company_invitations add constraint "company_invitations_company_id_fkey" FOREIGN KEY (company_id) REFERENCES companies(id) ON DELETE CASCADE;
alter table public.company_members add constraint "company_members_pkey" PRIMARY KEY (id);
alter table public.company_members add constraint "company_members_company_id_user_id_key" UNIQUE (company_id, user_id);
alter table public.erp_account_mappings add constraint "erp_account_mappings_default_kind_check" CHECK ((default_kind = ANY (ARRAY['revenue'::text, 'expense'::text])));
alter table public.erp_account_mappings add constraint "erp_account_mappings_category_id_fkey" FOREIGN KEY (category_id) REFERENCES categories(id) ON DELETE SET NULL;
alter table public.erp_account_mappings add constraint "erp_account_mappings_company_id_fkey" FOREIGN KEY (company_id) REFERENCES companies(id) ON DELETE CASCADE;
alter table public.erp_account_mappings add constraint "erp_account_mappings_company_id_erp_code_key" UNIQUE (company_id, erp_code);
alter table public.goals add constraint "goals_month_check" CHECK (((month >= 1) AND (month <= 12)));
alter table public.goals add constraint "goals_company_id_fkey" FOREIGN KEY (company_id) REFERENCES companies(id) ON DELETE CASCADE;
alter table public.goals add constraint "goals_company_id_year_month_kind_key" UNIQUE (company_id, year, month, kind);
alter table public.import_jobs add constraint "import_jobs_status_check" CHECK ((status = ANY (ARRAY['pending'::text, 'processing'::text, 'completed'::text, 'failed'::text])));
alter table public.import_jobs add constraint "import_jobs_company_id_fkey" FOREIGN KEY (company_id) REFERENCES companies(id) ON DELETE CASCADE;
alter table public.inventory_snapshots add constraint "inventory_snapshots_cost_cents_check" CHECK ((cost_cents >= 0));
alter table public.inventory_snapshots add constraint "inventory_snapshots_retail_cents_check" CHECK (((retail_cents IS NULL) OR (retail_cents >= 0)));
alter table public.inventory_snapshots add constraint "inventory_snapshots_company_id_fkey" FOREIGN KEY (company_id) REFERENCES companies(id) ON DELETE CASCADE;
alter table public.inventory_snapshots add constraint "inventory_snapshots_company_id_snapshot_date_key" UNIQUE (company_id, snapshot_date);
alter table public.parties add constraint "parties_company_id_fkey" FOREIGN KEY (company_id) REFERENCES companies(id) ON DELETE CASCADE;
alter table public.sales add constraint "sales_company_id_fkey" FOREIGN KEY (company_id) REFERENCES companies(id) ON DELETE CASCADE;
alter table public.sales add constraint "sales_company_id_period_start_seller_name_key" UNIQUE (company_id, period_start, seller_name);
alter table public.transactions add constraint "transactions_amount_cents_check" CHECK ((amount_cents >= 0));
alter table public.transactions add constraint "transactions_bank_account_id_fkey" FOREIGN KEY (bank_account_id) REFERENCES bank_accounts(id) ON DELETE SET NULL;
alter table public.transactions add constraint "transactions_category_id_fkey" FOREIGN KEY (category_id) REFERENCES categories(id) ON DELETE SET NULL;
alter table public.transactions add constraint "transactions_company_id_fkey" FOREIGN KEY (company_id) REFERENCES companies(id) ON DELETE CASCADE;
alter table public.transactions add constraint "transactions_cost_center_id_fkey" FOREIGN KEY (cost_center_id) REFERENCES cost_centers(id) ON DELETE SET NULL;
alter table public.transactions add constraint "transactions_party_id_fkey" FOREIGN KEY (party_id) REFERENCES parties(id) ON DELETE SET NULL;
commit;
